
import os
import pandas as pd


# Path to the local CSV generated by chembl_data.py
DATA_PATH = os.path.join(os.path.dirname(__file__), "CHEMBL-ADMET.csv")

def get_mechanism_metadata(
    chembl_target: str,
    selected_actions: list[str] | None = None,
) -> pd.DataFrame:
    """
    Retrieve ChEMBL compounds and precomputed ADMET properties
    from a local CSV file.

    Parameters
    ----------
    chembl_target : str
        ChEMBL target identifier (e.g., CHEMBL204).
    selected_actions : list[str] | None
        Selected mechanism-of-action types.

    Returns
    -------
    pd.DataFrame
        Filtered compounds with precomputed ADMET properties.
    """

    if not os.path.exists(DATA_PATH):
        raise FileNotFoundError(
            f"{DATA_PATH} not found."
        )

    df = pd.read_csv(DATA_PATH)

    # Filter by ChEMBL target
    df = df[
        df["target_chembl_id"] == chembl_target
    ].copy()

    # Filter by selected mechanisms of action
    if selected_actions is not None:
        df = df[
            df["action_type"].isin(selected_actions)
        ].copy()

    # Remove compounds without valid SMILES
    df = df.dropna(subset=["SMILES_Harmonized"])

    # Standardize SMILES column
    df["smiles"] = df["SMILES_Harmonized"]

    return df.reset_index(drop=True)


def get_chembl_adme_properties(
    chembl_target: str,
    selected_actions: list[str] | None = None,
) -> pd.DataFrame:
    """
    Retrieve precomputed ADMET properties for ChEMBL compounds.

    Parameters
    ----------
    chembl_target : str
        ChEMBL target identifier.
    selected_actions : list[str] | None
        Selected mechanism-of-action types.

    Returns
    -------
    pd.DataFrame
        Compounds with precomputed ADMET properties.
    """

    adme_chembl_df = get_mechanism_metadata(
        chembl_target,
        selected_actions
    )

    if adme_chembl_df.empty:
        return pd.DataFrame()

    # Create complementary BBB safety score
    if (
        "BBB_Martins" in adme_chembl_df.columns
        and "BBB_Martins_Safe" not in adme_chembl_df.columns
    ):
        adme_chembl_df["BBB_Martins_Safe"] = (
            1 - adme_chembl_df["BBB_Martins"]
        )

    return adme_chembl_df

